shellCommands.command:
PORT=3999 node server.mjs & SRV=$!; sleep 0.6;
echo "--- home ---"; curl -s http://localhost:3999/ | grep -oE '<h[12]>[^<]*' | head -8;
echo "--- add a book ---"; curl -s -o /dev/null -w '%{redirect_url}\n' -X POST http://localhost:3999/books -d 'title=Deep Work&author=Cal Newport&notes=great so far';
ID=$(curl -s http://localhost:3999/ | grep -oE '/books/[a-f0-9-]+' | head -1);
echo "--- detail ($ID) ---"; curl -s "http://localhost:3999$ID" | grep -oE 'Deep Work|Cal Newport|great so far|localhost:3999/books/[a-f0-9-]+' | sort -u;
echo "--- mark finished ---"; curl -s -o /dev/null -w '%{redirect_url}\n' -X POST "http://localhost:3999$ID/finish";
echo "--- finished section ---"; curl -s http://localhost:3999/ | grep -oE 'Finished|Currently reading' | sort | uniq -c;
echo "--- persisted to disk? ---"; test -f books.json && echo "books.json exists" && grep -o '"title":"Deep Work"' books.json;
kill $SRV 2>/dev/null
